CREATE POLICY "Members upload own claim evidence" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'claim-evidence' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Members read own claim evidence" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'claim-evidence' AND ((storage.foldername(name))[1] = auth.uid()::text OR public.has_role(auth.uid(), 'admin')));
CREATE POLICY "Members delete own claim evidence" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'claim-evidence' AND (storage.foldername(name))[1] = auth.uid()::text);